12→export default async function DashboardPage() {
13→  const user = await requireUser();
14→  if (!checkPermission(user.role, "dashboard", "view")) {
15→    redirect("/login");
16→  }
17→
18→  const columns = getDashboardColumns();
19→  const rows = getDashboardRows(user);
20→  const initialDetail = rows[0] ? getDashboardDetail(rows[0].id, user) : null;
21→  const users = user.role === "VIP" ? listUsers() : [];
22→  const departments = user.role === "VIP" ? getDepartmentOptions() : [];
23→
24→  // KPI computation (from summary page)
25→  const requestRows = rows.filter((r) => r.requestId !== null);
26→  const total = requestRows.length;
27→
28→  const completed = requestRows.filter((r) => {
29→    const step = r.values["현재단계"];
30→    return typeof step === "string" && (step.includes("완료") || step.includes("임용"));
31→  }).length;
32→
33→  const waiting = requestRows.filter((r) => {
34→    const step = r.values["현재단계"];
35→    return !step || step === "" || step === "대기";
36→  }).length;
37→
38→  const inProgress = total - completed - waiting;
39→
40→  const kpi = { total, inProgress, completed, waiting };
41→
42→  // Recent activity
43→  const recentActivity = requestRows.slice(0, 5).map((r, i) => {
44→    const fieldName = (r.values["(최종) 초빙분야"] as string) || "채용";
45→    const currentStep = (r.values["현재단계"] as string) || "";
46→    const statusLabel = currentStep || "진행중";
47→
48→    let status: "complete" | "progress" | "waiting" = "progress";
49→    if (currentStep.includes("완료") || currentStep.includes("임용")) {
50→      status = "complete";
51→    } else if (!currentStep || currentStep === "대기") {
52→      status = "waiting";
53→    }
54→
55→    return {
56→      id: r.id,
57→      deptName: r.deptName || "",
58→      description: `${fieldName} ${statusLabel}`,
59→      status,
60→      timeAgo: `${i + 1}일 전`,
61→    };
